// Exact-byte arg passing via bash ANSI-C quoting ($'...'), verified separately.
const {spawnSync}=require('child_process');
const BIN='/workspace/dataset/test4_executable';
function q(buf){
  let s="$'";
  for (const b of buf) s += '\\x'+b.toString(16).padStart(2,'0');
  return s+"'";
}
function runRaw(buf, prog){
  prog = prog || BIN;
  const cmd = prog+" --a "+q(buf);
  const r = spawnSync('/bin/bash',['-c',cmd],{encoding:'buffer'});
  return {out:(r.stdout||Buffer.alloc(0)).toString('hex'), err:(r.stderr||Buffer.alloc(0)).toString('hex'), errT:(r.stderr||Buffer.alloc(0)).toString('utf8'), code:r.status};
}
module.exports={runRaw,q,BIN};
