const {spawnSync}=require('child_process');
const BIN='/workspace/dataset/test4_executable';
function probeBatch(cps){
  const segs = cps.map(cp => 'a'+String.fromCodePoint(cp)+String.fromCodePoint(cp)+'b');
  const arg = segs.join('!');
  const r = spawnSync(BIN,['--a',arg],{encoding:'buffer'});
  if (r.status!==0) return {err:true, code:r.status, msg:(r.stderr||Buffer.alloc(0)).toString('utf8')};
  let out = r.stdout;
  if (out[out.length-1]===0x0a) out=out.slice(0,out.length-1);
  const parts = out.toString('binary').split('\x5f');
  return {parts, n:parts.length, outLen:out.length};
}
module.exports={probeBatch};
if (require.main===module){
  // positive control: mix known seps among high codepoints
  const ctrl=[0x1F600,0x10FFFF,0x21,0x2E80,0xE0001,0x5F,0x3000,0xA0,0x5C];
  console.log('control n=',probeBatch(ctrl).n,'expected', ctrl.length+2, JSON.stringify(probeBatch(ctrl).parts.map(p=>Buffer.from(p,'binary').toString('hex'))));
  // arg length test
  for (const k of [1000,4000,8000]){
    const cps=new Array(k).fill(0x41);
    const res=probeBatch(cps);
    console.log('batchsize',k, res.err?('ERR '+res.msg):('n='+res.n));
  }
}
